using Blux.UI.Tools;

namespace Blux.Playground.Client.Docs;

public static partial class Catalog
{
    /// <summary>
    /// Components of the Blux.UI.Tools package: the Package of their bundle entry is Blux.UI.Tools. The data list is documented on several pages, because every example that hands its
    /// prerendered result to the interactive render adds to the state the client sends back to the server (32 KB at most, SignalR refuses more) and one page cannot hold them all.
    /// </summary>
    private static readonly ComponentDoc[] DataList =
    [
        new("data-list", "DataList", "Data", "A table of rows loaded in memory, from a provider or from a database query (a Queryable, run asynchronously by the Blux.UI.Tools.EntityFrameworkCore adapter), with search, sortable columns, pagination, a result count, loading, empty and error states, and its state in the URL. Filters, counts, the filter panel and selection have their own pages.",
            [new("In-memory list with a schema", typeof(Examples.DataListExample), "The schema says which fields sort. Click a header to sort, use the pagination or the page size, then Back: the state is in the URL (mem.s, mem.p, mem.ps). Statically rendered, the headers and the pages are links and the page size is a GET form."),
             new("Provider", typeof(Examples.DataListProviderExample), "A provider loads the rows after a delay: placeholders on the first load, then the previous rows stay on screen while the next page loads. A newer request cancels the one it replaces."),
             new("State in the URL", typeof(Examples.DataListUrlExample), "No UrlKey, so the keys are s, p and ps. The footer counts the provider calls of this render: a prerendered list hands its result to the interactive render, which loads nothing a second time. The time zone is the one of the browser, null in static rendering."),
             new("Search", typeof(Examples.DataListSearchExample), "The default layout adds the search field when the schema declares search fields. The browser waits for a pause in the typing (300 ms, configurable with SearchDebounce or Debounce) and Enter searches at once; Escape and the clear button empty the field. Searching goes back to page 1 and replaces the address (find.q), so typing fills no history. Statically rendered, the field is a GET form that keeps the rest of the address. A search with no match shows its own empty state with a Clear search action."),
             new("A large first page", typeof(Examples.DataListLargeExample), "A prerendered list hands its first result to the interactive render only when it is small: PersistMaxBytes of BluxToolsOptions (16 KB by default) per list and PersistPageMaxBytes (8 KB) for the lists of a page together, because the client sends everything persisted to the server when a Server circuit starts and SignalR refuses 32 KB. A bigger result is not persisted, a warning names the list and its size, and the interactive render loads the rows once."),
             new("Error and retry", typeof(Examples.DataListErrorExample), "The provider fails while the address says ?broken=1. The error state offers a retry and keeps the rows that were on screen.")],
            [typeof(BxDataList<object>), typeof(BxDataListTable<object>), typeof(BxDataListColumn<object>), typeof(BxDataListPagination<object>), typeof(BxDataListResultCount<object>),
             typeof(BxDataListRefresh<object>), typeof(BxDataListErrorState<object>), typeof(BxDataListSearch<object>)]),
        new("data-list-filters", "DataListFilters", "Data", "Filters of a data list: filter tags with an editor in a popover, the Add filter menu, Clear filters, text, option, yes / no, number and date filters, in Live or Submit mode. Statically rendered the tags are links and the editors GET forms.",
            [new("Filters", typeof(Examples.DataListFilterExample), "A schema whose fields have filters (text, option with declared options and counts, boolean) adds the filter tags, an Add filter menu and Clear filters to the default layout. A tag reads \"Status is Paid, Pending +2\": it opens the editor of the filter in a popover, and its x removes the filter (Remove filter Status). Text applies after a pause in the typing, options and Yes / No / Any at once; each applied change adds a history entry (flt.f.status=Paid,Pending) and goes back to page 1, so Back undoes one change, and the typing of one text stays in the entry its first pause made. Option counts leave out the filter's own selection. Statically rendered the tags, operators, options and choices are links and a text filter is a GET form; opening the popover needs the script of Blux.UI, no .NET. A filter that matches nothing offers Reset filters."),
             new("Filters, Submit mode", typeof(Examples.DataListFilterSubmitExample), "ApplyMode=Submit keeps the changes in the editor until Apply (one history entry); Cancel, Escape or a click outside drop them."),
             new("Number filters", typeof(Examples.DataListNumberFilterExample), "A number filter has the operators is, is not, is greater than, is at least, is less than, is at most and is between. The editor is a number field with the limits and the step of the filter (Number(0, 10, 700)) and, with WithNumberDisplay, a slider next to it; a range has a From and a To field and a slider with two ends, either end can stay empty, and changing the operator keeps the value (it becomes the start of a range). Numbers are read and written in the culture of the user, and WithNumberFormat sets the format of the tag (N2 here: \"Amount is at least 100.00\"). Each applied change is a history entry and goes back to page 1 (num.f.amount.gte=100). Statically rendered the operators are links and the number is a GET form; a range sends its ends as num.f.amount.from and num.f.amount.to, and the slider needs the script and .NET, so it is left out. A filter that is not on yet starts with its default operator: switch it to a range from its tag."),
             new("Date filters", typeof(Examples.DataListDateFilterExample), "A date filter has the operators is, is not, is before, is after and is between. A single day is typed in a date field with a calendar; a range is picked on a range calendar, and the second click applies it (the first one applies nothing). Presets by operator are computed in the time zone of the user: Today, Yesterday and Start of month for is and is not; Today, 7 days ago and Start of month for is before; Today, 7 days ago and Start of year for is after; Today, Last 7 days, Last 30 days, This month, Last month and Year to date for a range. WithMaxRangeDays limits a range in the editor only (92 days here; a range in the URL or on the server is not checked): the calendar leaves out the days beyond it, and a preset that is longer keeps its last day. A filter exact to the hour or the minute (DataListFilter.Date(DateGranularity.Minute)) adds a time field and filters on the instant in the time zone of the user; one exact to the second keeps its tag and applies but has no editor. Statically rendered the presets are links and the day is a GET form with native date fields (a range sends dat.f.issued.from and dat.f.issued.to); on a timed filter a bound that is a whole day gets a date field, so applying the form keeps it a whole day, and a bound with a time gets a date-time field in the time zone of the user (the server reads a date-time without an offset in that zone); the script of Blux.UI.Tools leaves the time zone of the browser in a cookie (blux-timezone, path / or the path base, SameSite=Lax, about 13 months) that static renders and prerenders read through AddBluxServer() of the package Blux.UI.Server (call it in the server Program.cs; without it a static render cuts days in UTC and Development logs one warning), so the days are the user's; only the very first visit, before any script ran, a cookie with an unknown zone, or an app without AddBluxServer(), falls back to UTC. A single day picked on a timed filter, or from a preset, covers the whole local day (is Today, is not, before and after use its start and its end); with a time it is that hour or minute.")],
            [typeof(BxDataListFilterTags<object>), typeof(BxDataListAddFilter<object>), typeof(BxDataListClearFilters<object>)]),
        new("data-list-filter-panel", "DataListFilterPanel", "Data", "Every filter of a data list as a collapsible section, as a sidebar or in a slideover on a phone, with the same editors, limits and history as the filter tags.",
            [new("Filter panel", typeof(Examples.DataListFilterPanelExample), "BxDataListFilterPanel lists every filter of the schema as a collapsible section, next to the table as a sidebar: a text field, options with counts, Yes / No / Any, a number or a range with an optional slider, a day or a range of days. The sections use the editors of the filter tags and the Add filter menu, so the operators, the presets, the number and date parsing, the limits and the history are the same: each applied change is a history entry (pnl.f.status=Paid,Pending) and goes back to page 1. A section with a filter on starts expanded (and opens when a tag or the address turns one on) and shows how many values are on, the header shows the total, and Clear filters takes them all off. Each section also shows the number of rows the filters leave (\"Results: 120\", a live region), which matters in the slideover where the table is hidden. Statically rendered the panel is one GET form and its Apply button sends every field: text, number and date fields (a range as pnl.f.amount.from and pnl.f.amount.to, a day as a whole-day date field in the time zone of the blux-timezone cookie, like the other static date forms), a checkbox per option (they share the name of the filter, and the page reads them as one list, so the address carries one parameter per checked option; with the operator is the options are radios, which take one value), and Yes / No / Any radios; only the operators are links, and they apply at once and drop what was typed and not applied. A rule the form cannot edit (is empty, or an include-empty rule written in the address) goes back as it came, so applying never changes a filter you did not touch, and the script of Blux.UI.Tools leaves blank fields (of filters without a default rule) out of the address. A closed section is found by find-in-page, but without the script of Blux.UI a closed section cannot be opened: only the sections with a filter on are open."),
             new("Filter panel in a slideover", typeof(Examples.DataListFilterPanelSlideoverExample), "The recommended responsive pattern: the panel is a sidebar from the md breakpoint up, and on a phone a Filters button opens the same panel in a BxSlideover. Render the panel twice, once in each place, and hide the one that does not fit with CSS (hidden md:block and md:hidden): both read the one list state, so a filter applied in either shows in the other, and only one is ever on screen. ApplyMode=Submit keeps the changes of all sections until Apply (one history entry) and Reset drops them, and Clear filters stages the removal like any other change (Apply and Reset stay focusable when there is nothing to do, so the keyboard focus is not lost; Apply also takes the text that was typed a moment before); CloseOnApply adds data-bx-close to Apply so the slideover closes as the filters apply, interactive or statically rendered.")],
            [typeof(BxDataListFilterPanel<object>)]),
        new("data-list-facets", "DataListFacets", "Data", "Counts next to the options of a filter (facets) and option filters that load their options from a remote source.",
            [new("Counts on filters (facets)", typeof(Examples.DataListFacetsExample), "WithFacets() on an option or boolean filter shows how many rows have each option (or Yes and No) next to it, in the tag popovers and in the filter panel. By default a count leaves out the rule of its own filter, so the other options stay visible while the other filters narrow the numbers (WithFacetMode(FacetMode.IncludeSelf) keeps it). The include empty switch shows how many rows have no value. WithOptionSort orders options by count or by label and WithOptionLimit lists the first ones with a Show more button (a selected option is never held back; a statically rendered editor lists them all). Counts come from the executor of an in-memory list, from group-by queries of a Queryable (schema.FacetQueries, run asynchronously by the EF Core adapter) or from the Facets of the DataListResult of a provider. They are asked for when the filters or the search change, kept while the user pages or sorts, and asked again by Refresh; a prerendered result carries them to the interactive render and they count in its size. A filter with a count asks for at most MaxFacetBuckets distinct values (1000), and a facet over more is cut to the most counted ones."),
             new("Remote option filters", typeof(Examples.DataListRemoteOptionsExample), "WithRemoteOptions(provider, resolveSelected, pageSize, minLength) loads the options of an option filter from a remote source: the first page when the editor is shown, a search after a pause in the typing, the next page as the list scrolls (or with Load more), and an error with a Retry button. The paging, search and cancellation are those of the remote BxSelectMenu. A value restored from the address is labelled by the resolver (a tag reads Customer is Globex (Cypress Creek)); a picked option brings its label at once. With WithFacets() the options that are listed carry the counts of the facet. Interactive only: a statically rendered editor lists the selected values and the most counted options (at most the option limit, else the page size), all labelled by the resolver in one call on the server, leaves out a counted option the resolver does not know, and says that searching the rest needs JavaScript. WithOptionSort does not apply to remote options. A tag's editor loads when its popover opens, a filter panel section when it opens, the add filter menu when the filter is picked; nothing loads with the page. The counts of the options that are listed are asked for by value, so every page has its counts whatever the size of the facet. The labels a prerender resolved travel with its result, so the interactive render shows them at once.")],
            [typeof(BxDataListFilterEditor<object>)]),
        new("data-list-selection", "DataListSelection", "Data", "Row selection, a bar of bulk actions with an every-result scope and a toolbar menu of actions, for a list in memory and for a provider. Interactive only.",
            [new("Rows in memory", typeof(Examples.DataListSelectionExample), "A selection column is added when the list has a BxDataListSelectionActions bar (or Selectable, or a bound SelectedKeys), and the schema needs a RowKey. Tick rows with the mouse or Space; Shift+click ticks the range from the row touched last over the rows on screen; the box in the header ticks the rows of the page and is mixed (indeterminate) while only some are ticked. A list in memory keeps the selection across pages, but only the selected rows that the search and the filters still match stay selected, so a bulk action never reaches a row the user cannot see in the result. The bar shows how many rows are selected in a live region (nothing is announced until a row is ticked), \"Select all N results\" when the source knows the total (then the actions work on every matching row), the actions and Clear selection. Delete asks first with a dialog whose text counts the rows, runs while its button shows a spinner and unticks the rows when it succeeds (ClearSelection = DataListSelectionClear.Success); a failing action keeps the selection and reports through OnError. Use TargetCount of the context (not SelectedItems.Count) in a confirmation and in Visible and Disabled: it is the number of ticked rows, or the matching count under every result, which is what the action will act on. The bar is Sticky at the bottom of its list by default (Position = Fixed pins it to the window). The list shows no toasts of its own: report a result from OnExecute and a failure from OnError. ClearSelection = Success unticks the rows the action targeted (the ones ticked when it started); rows ticked while it ran stay. After it, if the focus was lost with the bar, it goes to the select-all box. The toolbar menu (BxDataListActionsDropdown) holds actions that need no selection. Selection and actions are interactive only: a statically rendered list has no checkbox column, no bar and no menu (a prerender of an interactive page shows the boxes disabled until the page is interactive, so it does not shift); use a link or a form for what must work without JavaScript."),
             new("Provider and bound keys", typeof(Examples.DataListSelectionProviderExample), "Over a provider (or a Queryable) the list keeps the selected rows of the page on screen only: a new page, sort, search or filter drops the rows that left (SelectionScope.Page applies to a list in memory too). @bind-SelectedKeys reads and sets the selection as strings (the RowKey of the schema); give a new set when you change it, and the keys the list cannot keep (rows not on the page) are dropped and reported back. Select all N results appears when the provider returns a TotalCount; an action on every result gets Scope = All, no rows, MatchingCount and the Request (search, filters and sort, no paging) to send to the server, which applies it with schema.Apply, so a bulk action never needs the rows on the client. The every-result choice goes back to the ticked rows when the user ticks a row or changes the search or the filters."),
             new("Row actions", typeof(Examples.DataListRowActionsExample), "RowActions of BxDataListTable adds a last column of DataListRowAction items (or place a BxDataListRowActions part in a column template). On a wide screen the first RowActionsMaxVisible actions (3 by default) are buttons and the rest sit in a menu named Actions for {row label} (Actions for row N without a RowLabel); 0 keeps one button per row. Group puts actions together, with a divider between groups in the order of their first visible action; an action with Children opens a submenu and always sits in the menu. Below the md breakpoint one button opens a bottom sheet with every action and, under a disabled one, its DisabledReason; the sheet is rendered once per row and CSS switches the presentations, so nothing is duplicated. Visible hides an action for a row, Disabled and Loading (and the run itself, which shows a spinner) block it, and an action that is hidden, disabled, loading or already running for the row is ignored. Confirm asks first, with the same dialog as the bulk actions. A failure, an exception or context.Fail(message), keeps the list as it is, raises OnRowActionError and never throws to the page; RefreshOnSuccess loads the list again after a success. When a successful action removes its row and the focus was in it, the focus moves to the actions of the next row, else to the table. Row actions are interactive only, except an action with Href, which is a plain link in a statically rendered list (the others are not drawn there, and a prerender of an interactive page shows only the links until it is interactive).")],
            [typeof(BxDataListSelectionActions<object>), typeof(BxDataListActionsDropdown<object>), typeof(BxDataListRowActions<object>)]),
        new("data-list-cursor", "DataListCursor", "Data", "Keyset cursor paging with an infinite loader (automatic scroll sentinel or manual Load more, inline retry on error, link fallback in static SSR) and opt-in row virtualization.",
            [new("Cursor paging (manual)", typeof(Examples.DataListCursorExample), "PagingMode=Cursor uses keyset cursors (the schema needs a RowKey for in-memory or Queryable sources). BxDataListInfiniteLoader with Auto=false appends each page when Load more is clicked, updates the result count, and announces \"No more items\" at the end. Changing the search or the sort resets the cursor to the first page. Statically rendered, Load more is a link (?cur.c=...) paired with Back to start once past the first page."),
             new("Infinite scroll and load-more error", typeof(Examples.DataListCursorAutoExample), "With Auto=true (the default), BxDataListInfiniteLoader wraps BxInfiniteScroll with a 320 px root margin (configurable via Root and RootMargin) and appends pages as the sentinel enters the viewport. When loading the next page fails (?failmore=1), the rows loaded so far stay on screen and an inline alert offers Retry (or a custom ErrorTemplate)."),
             new("Virtualized rows", typeof(Examples.DataListVirtualizedExample), "PagingMode=None loads every matching row without a pagination footer, and Virtualize=true on BxDataListTable renders only the rows around the scroll viewport with Blazor's Virtualize (tr spacers, sticky header, single-line fixed row heights matching DataListDensity: 36, 44 or 60 px, aria-rowcount and aria-rowindex). Virtualization is interactive only: static renders and prerenders draw regular rows.")],
            [typeof(BxDataListInfiniteLoader<object>)]),
        new("data-list-columns", "DataListColumns", "Data", "Column configurator popover (show/hide, reorder, pin to start or end, search, reset), pointer-drag and keyboard column resizing, and cookie persistence read on the server for zero-flash SSR.",
            [new("Column panel, pinning, resize and cookie persistence", typeof(Examples.DataListColumnsExample), "BxDataListColumnPanel opens a popover listing every non-Required column with a visibility checkbox, Move up/down buttons, Pin to start/end toggles, optional search (SearchThreshold, 30 by default) and Reset columns. BxDataListTable Resizable=true adds pointer-drag and keyboard (ArrowLeft/ArrowRight/Home) resize handles on headers, and Pinned columns stick to the start or end edge with logical inset offsets. Setting PreferencesKey on BxDataList stores visibility, order, pinning and widths in a compact path-scoped cookie (blux-dl-cols-<key>) that AddBluxServer() reads on the server, so reloads and SSR renders match from the very first paint. Interactive only: the panel is hidden in static SSR.")],
            [typeof(BxDataListColumnPanel<object>)]),
        new("data-list-empty", "DataListEmpty", "Data", "The empty state of a data list: a localized title and hint, an icon and room for actions.",
            [new("Default texts", typeof(Examples.DataListEmptyExample), "The title and the hint are localized in the 12 languages of Blux UI and follow the culture of the user."),
             new("With actions", typeof(Examples.DataListEmptyActionsExample), "Actions sit under the text; an empty Description or Icon hides that part.")],
            [typeof(BxDataListEmpty)]),
    ];
}
